+//! #2283: 2D Chamfer in a setup that holds the part turned about TWO
+//! axes (90 degrees about X, then 90 degrees about Z). The chamfer mill
+//! (`CM-0600-90`) rides the loop of one picked edge on the face that is
+//! up in the setup frame. The op is generated three times:
+//! - in the turned setup (the part as modelled, the setup aligned);
+//! - on the part with that very turn baked into its facets, unaligned;
+//! - on the part as modelled, unaligned.
+//!
+//! The first two must cut and post the same program, and the cut must
+//! ring the turned top face (X [10, 20], Y [-5, 5], Z 15 in the setup
+//! frame). The third must cut a different path, so a generator that
+//! read the model frame fails.
+//!
+//! Provenance: an analytic L prism and a rigid turn read back from the
+//! stored alignment (plain rigid-body math); no vendor material
+//! consulted.
+//!
+//! Gate map (#2283): covers app::setup_align, app::operation::job,
+//! app::operation::boundary_picks, app::operation::material,
+//! app::posting, app::stock_sim, app::stock_sim_breaks. Lane shape
+//! (M4.4): every test here runs in seconds.
+
+use camcraft_app::cl::{MoveKind, Toolpath};
+use camcraft_app::commands::{AddTool, AlignPartToSetup, CreateOperation, CreateSetup, GenerateOperation, History, ImportModel, SetStock};
+use camcraft_app::geometry::{Mesh, Point3, Triangle, feature, transform_point};
+use camcraft_app::machining2d::Side;
+use camcraft_app::operation::{self, FeatureSel, GeoSel, Height, HeightReference, OpParams, SrcRef};
+use camcraft_app::schema::Location;
+use camcraft_app::stock::StockShape;
+use camcraft_app::tools::catalog;
+use camcraft_app::{model, posting, setup_align, world::new_world};
+use flecs_ecs::prelude::World;
+
+const TOOL: &str = "CM-0600-90";
+/// About X, about Y, about Z (degrees): two axes, so a generator that
+/// reads only a Z turn, or the wrong order, cuts a different place.
+const TURN: [f64; 3] = [90.0, 0.0, 90.0];
+
+/// The L outline as modelled, counter-clockwise: arms of 30 and 20 mm.
+const L: [(f64, f64); 6] = [(0.0, 0.0), (30.0, 0.0), (30.0, 8.0), (10.0, 8.0), (10.0, 20.0), (0.0, 20.0)];
+
+/// An L prism, z in [0, 10], as modelled.
+fn l_prism() -> Vec<Triangle> {
+    let b = |i: usize| Point3::new(L[i].0, L[i].1, 0.0);
+    let t = |i: usize| Point3::new(L[i].0, L[i].1, 10.0);
+    let n = L.len();
+    let mut f = Vec::new();
+    for i in 1..n - 1 {
+        f.push(Triangle::new(t(0), t(i), t(i + 1)));
+        f.push(Triangle::new(b(0), b(i + 1), b(i)));
+    }
+    for i in 0..n {
+        let j = (i + 1) % n;
+        f.push(Triangle::new(b(i), b(j), t(j)));
+        f.push(Triangle::new(b(i), t(j), t(i)));
+    }
+    f
+}
+
+#[derive(Clone, Copy, Debug, PartialEq)]
+enum Case {
+    /// The part as modelled in a setup that holds it turned.
+    Turned,
+    /// The turn baked into the part's facets; the setup is unaligned.
+    Baked,
+    /// The part as modelled; the setup is unaligned.
+    Modelled,
+}
+
+/// The alignment that `TURN` stores, read back from a scratch document.
+fn stored_turn() -> Location {
+    let world = new_world();
+    let mut h = History::default();
+    h.execute(&world, ImportModel::from_mesh("part", Mesh::from_facets(l_prism())));
+    h.execute(&world, CreateSetup::new(&world, None, None).expect("Setup1"));
+    h.execute(&world, AlignPartToSetup::angles(&world, "Setup1", TURN).expect("turn"));
+    setup_align::stored(&world, "Setup1").expect("the turn is stored")
+}
+
+/// The part, Setup1, the chamfer mill and one stock box that holds the
+/// part in each case. The stock is set after the turn: furniture.
+fn document(case: Case) -> (World, History) {
+    let world = new_world();
+    let mut h = History::default();
+    let facets = match case {
+        Case::Baked => {
+            let a = stored_turn();
+            let p = |q: Point3| transform_point(q, a.pos, a.rot);
+            l_prism().into_iter().map(|t| Triangle::new(p(t.a), p(t.b), p(t.c))).collect()
+        }
+        Case::Turned | Case::Modelled => l_prism(),
+    };
+    h.execute(&world, ImportModel::from_mesh("part", Mesh::from_facets(facets)));
+    let tool = catalog().into_iter().find(|(n, _)| *n == TOOL).map(|(_, t)| t).expect("chamfer mill");
+    h.execute(&world, AddTool::new(&world, TOOL, tool).expect("add tool"));
+    h.execute(&world, CreateSetup::new(&world, None, None).expect("Setup1"));
+    if case == Case::Turned {
+        h.execute(&world, AlignPartToSetup::angles(&world, "Setup1", TURN).expect("turn about X and Z"));
+    }
+    // The turned part is X [10, 20], Y [-5, 25], Z [-5, 15]; the part as
+    // modelled is X [0, 30], Y [0, 20], Z [0, 10]. The box holds both.
+    let at = Location { pos: Point3::new(15.0, 10.0, -6.0), ..Default::default() };
+    let stock = StockShape::Box { dx: 44.0, dy: 54.0, dz: 21.0 };
+    h.execute(&world, SetStock::new(&world, stock, at).expect("stock"));
+    (world, h)
+}
+
+/// A 1 mm, 45-degree chamfer on the part's top edge: the top plane
+/// reads the part's top (`TopOfModel`), so the height reads the setup
+/// frame too.
+fn chamfer() -> OpParams {
+    OpParams::Chamfer2D {
+        width: 1.0,
+        angle_deg: 45.0,
+        clearance_z: Height::fixed(30.0),
+        retract_z: None,
+        top_z: Height::of(HeightReference::TopOfModel, 0.0),
+        feed: 800.0,
+        plunge_feed: 200.0,
+        climb: true,
+        side: Side::Auto,
+        tolerance: 0.01,
+        tilt: None,
+    }
+}
+
+/// ONE picked edge on the face that is up at the part's top in Setup1's
+/// frame, closed around that face's loop the way the panel's "extend to
+/// loop" does (`extend_to_loop_in`, setup frame).
+fn top_edge_loop(world: &World) -> SrcRef {
+    let part = model::find_by_name(world, "part").expect("part");
+    let f = model::features_of(world, &part).expect("features");
+    let pose = setup_align::pose_in(world, &part, Some("Setup1")).expect("pose");
+    let top = setup_align::part_aabb_in(world, Some("Setup1")).expect("bounds").max.z;
+    let up = |p: &[f64; 3]| (transform_point(Point3::new(p[0], p[1], p[2]), pose.pos, pose.rot).z - top).abs() < 1e-6;
+    let edge = feature::chains(&f)
+        .into_iter()
+        .find(|c| {
+            let pts = feature::chain_points(&f, c);
+            pts.len() >= 2 && pts.iter().all(up)
+        })
+        .expect("an edge on the top face");
+    let pick = GeoSel { entity: "part".into(), feature: FeatureSel::Chain(edge.id) };
+    let picks = operation::extend_to_loop_in(world, Some("Setup1"), &[pick]).expect("the edge closes to a loop");
+    assert!(picks.len() > 1, "the loop holds more than the picked edge: {picks:?}");
+    SrcRef::Selection(picks)
+}
+
+/// Generate the chamfer; the turned and baked cases must also verify
+/// clean, simulate without a gouge and post.
+fn generate_on(case: Case) -> Result<(Toolpath, String), String> {
+    let (world, mut h) = document(case);
+    let src = top_edge_loop(&world);
+    h.execute(&world, CreateOperation::new(&world, "Chamfer", TOOL, src, chamfer()).expect("create"));
+    let cmd = GenerateOperation::new(&world, "Chamfer").map_err(|e| e.to_string())?;
+    h.execute(&world, cmd);
+    let entity = model::find_by_name(&world, "Chamfer").expect("op");
+    let cached = model::toolpath_of(&world, &entity).ok_or_else(|| -> String {
+        format!("no path in the cache: {:?}", operation::status_of(&world, &entity))
+    })?;
+    if case == Case::Modelled {
+        return Ok((cached.path, String::new()));
+    }
+    assert!(!cached.path.moves.is_empty(), "{case:?}: the cut contains moves");
+    assert!(!cached.warnings.iter().any(|w| w.blocks_post()), "{case:?}: unsafe path: {:?}", cached.warnings);
+    let sim = camcraft_app::stock_sim::simulate_document(&world).expect("the part is judged");
+    assert_eq!(sim.dev.gouge_cells, 0, "{case:?}: gouge {} at {:?}", sim.dev.max_gouge, sim.dev.max_gouge_at);
+    let nc = posting::post_setup_unwritten(&world).expect("a clean path posts").program;
+    Ok((cached.path, nc))
+}
+
+/// The cutting moves (feed and plunge) below the top plane.
+fn cuts(path: &Toolpath, top: f64) -> Vec<Point3> {
+    path.moves.iter().filter(|m| m.kind != MoveKind::Rapid && m.to.z < top - 1e-6).map(|m| m.to).collect()
+}
+
+/// #2283: the turned setup and the baked part cut the same chamfer ride
+/// and post the same program; the ride rings the turned top face in the
+/// setup frame; the part as modelled cuts another path.
+#[test]
+fn turned_chamfer_cuts_like_the_baked_part() {
+    let (turned, t_nc) = generate_on(Case::Turned).unwrap_or_else(|e| panic!("2D Chamfer generates turned: {e}"));
+    let (baked, b_nc) = generate_on(Case::Baked).unwrap_or_else(|e| panic!("2D Chamfer generates baked: {e}"));
+    assert_eq!(turned.moves.len(), baked.moves.len(), "same move count");
+    for (i, (a, b)) in turned.moves.iter().zip(&baked.moves).enumerate() {
+        assert_eq!(a.kind, b.kind, "move {i} kind");
+        let d = (a.to.x - b.to.x).abs().max((a.to.y - b.to.y).abs()).max((a.to.z - b.to.z).abs());
+        assert!(d < 1e-6, "move {i}: turned {:?} baked {:?}", a.to, b.to);
+    }
+    assert_eq!(t_nc, b_nc, "the same setup geometry posts the same program");
+
+    // The aligned geometry: the turned top face is the square X [10, 20],
+    // Y [-5, 5] at Z 15. The cone (6 mm across) rides its rim, so every
+    // cut stands within the tool radius of that square and below Z 15 by
+    // no more than the cone's reach; the ride is centred on the square
+    // and as wide in X as in Y.
+    let pts = cuts(&turned, 15.0);
+    assert!(!pts.is_empty(), "the ride cuts below the top: {:?}", turned.notes);
+    for p in &pts {
+        assert!(p.x > 10.0 - 3.0 - 1e-6 && p.x < 20.0 + 3.0 + 1e-6, "cut X {p:?} off the turned face");
+        assert!(p.y > -5.0 - 3.0 - 1e-6 && p.y < 5.0 + 3.0 + 1e-6, "cut Y {p:?} off the turned face");
+        assert!(p.z > 15.0 - 3.0 - 1e-6, "cut Z {p:?} deeper than the cone reaches");
+        let inside = p.x > 10.0 + 1e-6 && p.x < 20.0 - 1e-6 && p.y > -5.0 + 1e-6 && p.y < 5.0 - 1e-6;
+        let near = (p.x - 10.0).abs().min((p.x - 20.0).abs()).min((p.y + 5.0).abs()).min((p.y - 5.0).abs());
+        assert!(!inside || near < 3.0, "cut {p:?} stands far inside the face, not on its rim");
+    }
+    let (mut lo, mut hi) = ([f64::INFINITY; 2], [f64::NEG_INFINITY; 2]);
+    for p in &pts {
+        (lo[0], lo[1], hi[0], hi[1]) = (lo[0].min(p.x), lo[1].min(p.y), hi[0].max(p.x), hi[1].max(p.y));
+    }
+    assert!((0.5 * (lo[0] + hi[0]) - 15.0).abs() < 1e-3, "ride centred on X 15: {lo:?} {hi:?}");
+    assert!((0.5 * (lo[1] + hi[1])).abs() < 1e-3, "ride centred on Y 0: {lo:?} {hi:?}");
+    assert!(((hi[0] - lo[0]) - (hi[1] - lo[1])).abs() < 1e-3, "a square ride: {lo:?} {hi:?}");
+
+    // The model frame is another place: a generator that read it fails.
+    let (modelled, _) = generate_on(Case::Modelled).unwrap_or_else(|e| panic!("2D Chamfer generates as modelled: {e}"));
+    let far = modelled.moves.len() != turned.moves.len()
+        || modelled.moves.iter().zip(&turned.moves).any(|(a, b)| (a.to.x - b.to.x).abs() + (a.to.y - b.to.y).abs() + (a.to.z - b.to.z).abs() > 1e-3);
+    assert!(far, "the turn must change the path");
+}
+
+/// An unaligned setup is untouched: the door has nothing to say and the
+/// chamfer on the part as modelled rides the L's top (Z 10) as before.
+#[test]
+fn unaligned_chamfer_rides_the_modelled_top() {
+    let (world, _) = document(Case::Modelled);
+    let op = camcraft_app::schema::Operation {
+        tool: TOOL.into(),
+        src: top_edge_loop(&world),
+        params: chamfer(),
+        stamp: None,
+        setup: Some("Setup1".into()),
+        area: Default::default(),
+        coolant: Default::default(),
+        after: Default::default(),
+        suppressed: false,
+    };
+    assert_eq!(setup_align::generation_problem(&world, &op), None, "no alignment, no door");
+    let (path, _) = generate_on(Case::Modelled).unwrap_or_else(|e| panic!("2D Chamfer generates as modelled: {e}"));
+    let pts = cuts(&path, 10.0);
+    assert!(!pts.is_empty(), "the ride cuts below the L top");
+    assert!(pts.iter().all(|p| p.z > 10.0 - 3.0 - 1e-6 && p.x > -3.0 - 1e-6 && p.x < 33.0 + 1e-6), "{pts:?}");
+}
